WITH cleaned AS (SELECT id, supplier_name, country, city, rating, TRIM(supplier_name) AS clean_supplier_name, ROUND(rating * 1.07, 2) AS adjusted_rating FROM suppliers WHERE city IS NOT NULL AND country = 'SG'), latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY adjusted_rating ASC NULLS LAST, id ASC) AS rn FROM cleaned QUALIFY rn = 1), kept AS (SELECT s.* FROM latest s WHERE EXISTS (SELECT 1 FROM products c WHERE c.supplier_id = s.id AND c.brand IN ('Initech', 'Acme'))), with_last AS (SELECT s.*, x.cost, x.product_launch_date FROM kept s JOIN LATERAL (SELECT c.cost, c.launch_date AS product_launch_date FROM products c WHERE c.supplier_id = s.id ORDER BY c.stock_qty DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT CASE WHEN rating >= 4.2 THEN 'LARGE' ELSE 'SMALL' END AS rating_tier, city, COUNT_IF(country = 'TH') AS th_events, ROUND(AVG(adjusted_rating), 2) AS avg_adjusted_rating, PERCENTILE_APPROX(adjusted_rating, ARRAY(0.25, 0.5, 0.75)) AS adjusted_rating_quartiles, SUM(adjusted_rating) AS total_adjusted_rating, COUNT(*) FILTER (WHERE city = 'London') AS london_rows, SUM(CASE WHEN country = 'UK' THEN adjusted_rating ELSE 0 END) AS uk_adjusted_rating FROM with_last GROUP BY CUBE (CASE WHEN rating >= 4.2 THEN 'LARGE' ELSE 'SMALL' END, city) ORDER BY total_adjusted_rating ASC NULLS LAST
